import{_ as a}from"./chunks/popup-translate.CYMtVXLB.js";import{_ as e,o,c as r,a2 as l}from"./chunks/framework.CfwCq2QB.js";const m=JSON.parse('{"title":"弹窗查词","description":"","frontmatter":{},"headers":[],"relativePath":"features/lookup.md","filePath":"features/lookup.md"}'),s={name:"features/lookup.md"};function i(n,t,d,c,p,u){return o(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="弹窗查词" tabindex="-1">弹窗查词 <a class="header-anchor" href="#弹窗查词" aria-label="Permalink to &quot;弹窗查词&quot;">​</a></h1><p>一句话：弹窗「翻译」页可以直接查词，支持有道 / 微软 / Google / AI 四种引擎，单词会并行展示词典结果。</p><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><p>按 <code>Alt+1</code> 打开弹窗，「翻译」页顶部输入框输入单词或短句，回车或点「查询」：</p><ul><li><strong>有道 / 微软 / 谷歌</strong>：免费即用，单词查询会并行展示词典释义（音标、词性、常见义项）</li><li><strong>AI</strong>：用你的对话模型解释词汇、辨析用法，适合查术语和惯用表达；需要先在 <a href="/dev-go-docs/settings/models.html">AI 模型</a>里配置</li></ul><p>结果下方有<strong>复制</strong>和<strong>朗读</strong>按钮。</p><img src="'+a+'" alt="弹窗查词" style="width:60%;display:block;margin-left:auto;margin-right:auto;"><p><em>图：弹窗「翻译」页查词——输入单词或短句即查，结果带复制与朗读。</em></p><h2 id="相关能力" tabindex="-1">相关能力 <a class="header-anchor" href="#相关能力" aria-label="Permalink to &quot;相关能力&quot;">​</a></h2><p>查词页同时也是整页翻译的控制台：</p><ul><li><strong>翻译引擎 / 目标语言</strong>：在查词框下方直接切换，对整页翻译和划词翻译同时生效</li><li><strong>总是翻译该网站</strong>：把当前网站加进自动整页翻译列表</li><li><strong>翻译当前页面 / 显示原文</strong>：切换整页翻译，详见<a href="/dev-go-docs/features/page-translate.html">整页双语翻译</a></li><li><strong>悬停翻译</strong>：设置页「翻译」里开启，鼠标悬停按一下 <code>Alt</code> 只翻当前段落</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>选 AI 引擎但还没配置模型时，会提示「还没有配置翻译模型」，点「去配置」即可</li><li>微软引擎免翻墙直连；Google 引擎需要代理</li></ul>',13)])])}const _=e(s,[["render",i]]);export{m as __pageData,_ as default};
